/**
 * SHEEGOW ACADEMY — i18n translations
 *
 * Three locales are supported:
 *   - en  English (default, LTR)
 *   - so  Soomaali (Somali, LTR)
 *   - ar  العربية (Arabic, RTL)
 *
 * Keys are flat strings ("namespace.key") so that lookup is a single
 * map access. Missing keys fall back to English, then to the key itself.
 *
 * IMPORTANT: keep this file free of any React or DOM code so it can be
 * imported from both client and server (and from the non-React `t` helper
 * in ./index.ts).
 */

export type Locale = "en" | "so" | "ar";

export const LOCALES: Locale[] = ["en", "so", "ar"];

export const DEFAULT_LOCALE: Locale = "en";

/** Display metadata for each locale — used by the LanguageToggle UI. */
export const LOCALE_META: Record<
  Locale,
  { label: string; nativeLabel: string; flag: string; dir: "ltr" | "rtl" }
> = {
  en: { label: "English", nativeLabel: "English", flag: "🇬🇧", dir: "ltr" },
  so: { label: "Somali", nativeLabel: "Soomaali", flag: "🇸🇴", dir: "ltr" },
  ar: { label: "Arabic", nativeLabel: "العربية", flag: "🇸🇦", dir: "rtl" },
};

