    // ── About ──
    "about.eyebrow": "Our Story",
    "about.title": "About",
    "about.heroDesc":
      "We exist to bring quality, live English education to students everywhere. No recorded videos. No lonely self-study. Just real teachers, real conversations, real progress.",
    "about.exploreCourses": "Explore Courses",
    "about.getInTouch": "Get in Touch",
    "about.missionDesc":
      "To make high-quality, interactive English education accessible to every learner — through live classes taught by caring expert teachers. We exist to break the barrier of recorded, passive learning and replace it with conversation, practice, and confidence.",
    "about.visionDesc":
      "A world where every student — from primary school to working professional — can speak English confidently. Where live classes replace lonely videos, where teachers know their students by name, and where a better future is just a live class away.",
    "about.storyEyebrow": "The Story",
    "about.storyTitle": "Built for learners, by learners",
    "about.storyP1":
      "SHEEGOW ACADEMY started with a simple frustration: too many English courses were just recordings. You watched a video, took a quiz, and forgot everything. There was no speaking, no practice, no real conversation — the very things that make a language stick.",
    "about.storyP2a": "Our founder and general manager,",
    "about.storyP2b":
      ", decided to fix this. An English language expert with a university degree, he holds multiple language certifications and brings 15 years of hands-on teaching experience. We built a platform where every single class is",
    "about.storyP2c":
      ". Where you see your teacher, hear your classmates, raise your hand, and speak English out loud from day one.",
    "about.storyP3":
      "Today, students learn with us — from absolute beginners taking their first class to IELTS candidates preparing for university abroad. We learn on phones and laptops. We come from different countries, but we share one goal: to speak English with confidence.",
    "about.storyP4a": "That's the SHEEGOW difference.",
    "about.storyP4b": "Live classes, not recorded videos.",
    "about.valuesEyebrow": "Our Values",
    "about.valuesTitle": "What we believe in",
    "about.valuesDesc":
      "Six principles that shape every class, every course, every decision we make.",
    "about.valueLiveFirstTitle": "Live-first learning",
    "about.valueLiveFirstDesc":
      "We believe English is meant to be spoken, not watched. Every class is a real-time video session with a teacher.",
    "about.valueAccessibleTitle": "Accessible to all",
    "about.valueAccessibleDesc":
      "Quality English education should reach every learner around the world who wants to learn English — no matter where you start.",
    "about.valueQualityTitle": "Quality teaching",
    "about.valueQualityDesc":
      "Our teachers are TESOL-certified and specialize in teaching English to students from every background.",
    "about.valueCommunityTitle": "Community",
    "about.valueCommunityDesc":
      "Learning is social. We build small, supportive cohorts where students practice together and grow together.",
    "about.valueRespectTitle": "Cultural respect",
    "about.valueRespectDesc":
      "We respect every culture and background. Our lessons help you open new doors without leaving your identity behind.",
    "about.valueImprovementTitle": "Continuous improvement",
    "about.valueImprovementDesc":
      "We listen to student feedback every week and refine our courses to serve you better.",
    "about.leadershipEyebrow": "Leadership",
    "about.leadershipTitle": "Meet the founder & general manager",
    "about.leadershipDesc": "The English language expert behind SHEEGOW ACADEMY.",
    "about.founderBadge": "Founder & General Manager",
    "about.founderSpecialty": "English Language Expert · 15+ Years of Experience",
    "about.founderBio":
      "Ciise holds a university degree in English and multiple language certifications. With 15 years of teaching experience, he leads SHEEGOW ACADEMY with one goal: helping learners everywhere speak English with confidence through live, interactive classes.",
    "about.universityDegree": "University degree",
    "about.multipleCertificates": "Multiple language certificates",
    "about.teaching15Years": "15 years of teaching experience",
    "about.teacherEyebrow": "Meet Your Teacher",
    "about.teacherTitle": "One expert. Every class live.",
    "about.teacherDesc":
      "All courses are taught by founder Ciise Mohamed Sheeq (SHEEGOW), an English language expert with 15 years of experience — live and interactive, never recorded.",
    "about.founderTeacherBadge": "Founder & Teacher",
