    "about.eyebrow": "Sheekadeenna",
    "about.title": "Ku saabsan",
    "about.heroDesc": "Waxaan jirna si aan u keeno barasho Ingiriis oo tayo sareysa, live arday kasta. Ma jiro video qoran. Ma jiro is-barasho keli. Macallimiin dhab ah, wada-hadal dhab ah, habayn dhab ah.",
    "about.exploreCourses": "Dhuxusho Koorsooyinka",
    "about.getInTouch": "Nala soo xidhiidh",
    "about.missionDesc": "Si aan u dhigno barasho Ingiriis oo tayo sareysa, isdhaafsi u heli karto arday kasta — fasalada live oo macallimiin xanaanayaan khibrad leh. Waxaan jirna si aan u jebino caqabada barasho qoran, gacan-siin ah oo lagu beddelo wada-hadal, dhaqan iyo kalsooni.",
    "about.visionDesc": "Adduun arday kasta — dugsi hoose ilaa xirfadley — uu Ingiriiska si kalsooni u hadli karo. Halka fasalada live ay ku beddelaan video keli, halka macallimiintu ardayda magacyadood yaqaanaan, iyo halka mustaqbal wanaagsan uu fasal live u dhow yahay.",
    "about.storyEyebrow": "Sheekada",
    "about.storyTitle": "Loo sameeyay ardayda, ardayda ayaa dhigay",
    "about.storyP1": "SHEEGOW ACADEMY waxay bilaabatay niyad-jab fudud: koorsooyin Ingiriis badan oo keliya rikoor ahaa. Waxaad daawanaysay video, waxaad quizz u qabatay, oo waxaad halmaantay dhamaan. Ma jirin hadal, dhaqan, ama wada-hadal dhab ah — waxyaabaha luqad ku dhaca.",
    "about.storyP2a": "Aasaasaheenna iyo maareeyaha guud,",
    "about.storyP2b": ", ayaa go'aansaday inuu tan saxo. Khabiir luqadda Ingiriis oo heysa digri jaamacad, wuxuu haystaa shahaadooyin luqad badan oo 15 sano khibrad barasho la yimaada. Waxaan dhisnay boggag oo cashar kastaba",
    "about.storyP2c": ". Halka aad eegaysid macallinkaaga, maqasha saaxiibadaada, kor u qaaddo gacanta, oo Ingiriiska hadashid codka maalinta koowaad.",
    "about.storyP3": "Maanta, ardayda waxay nala barataan — bilaabasho dhab ah oo casharka koowaad qaadanaya ilaa arday IELTS jaamacad dibadda u diyaar garoobaya. Waxaan barannaa telefoon iyo laptop. Waxaan ka yimaad waddan kasta, laakiin waxaan wadaagnaa hal hadaf: Ingiriiska ku hadal kalsooni.",
    "about.storyP4a": "Kaasi waa farqiga SHEEGOW.",
    "about.storyP4b": "Fasalada live, ma video qoran.",
    "about.valuesEyebrow": "Qiimahaaga",
    "about.valuesTitle": "Waxaan rumeysnaa",
    "about.valuesDesc": "Lix mabda oo haddaba cashar kasta, koorso kasta, go'an kasta oo aan qaadano.",
    "about.valueLiveFirstTitle": "Barasho live-marka hore",
    "about.valueLiveFirstDesc": "Waxaan rumeysnaa Ingiriiska in la hadlo, ma la eego. Cashar kastaba waa video real-time oo macallin la.",
    "about.valueAccessibleTitle": "U heli karo dhammaan",
    "about.valueAccessibleDesc": "Barasho Ingiriis oo tayo sareysa waa inuu gaaraa arday kasta adduunka oo Ingiriis baran rabo — meel kasta oo aad ka bilowdo.",
    "about.valueQualityTitle": "Tayada barashada",
    "about.valueQualityDesc": "Macallimiinteenu waa TESOL-certified oo ku takhasusa barista Ingiriiska arday kasta oo asal kasta ah.",
    "about.valueCommunityTitle": "Bulsho",
    "about.valueCommunityDesc": "Barashu waa bulsho. Waxaan dhisnaa kooxo yaryar, taageerayaan oo ardaydu wada dhaqantoonaan o wada koraan.",
    "about.valueRespectTitle": "Dhaqan-sinnaan",
    "about.valueRespectDesc": "Waxaan maamuusnaa dhaqan iyo asal kasta. Casharrahaagu waxay kuu furayaan albaab cusub adigoon ka tagin aqoonsigaaga.",
    "about.valueImprovementTitle": "Habaynta sii wadidda",
    "about.valueImprovementDesc": "Waxaan maqalnaa caqabad ardayda toddobaad kasta oo waxaan hagaajinaa koorsooyinka si aan ku caawinno.",
    "about.leadershipEyebrow": "Hogaaminta",
    "about.leadershipTitle": "La kulul aasaasaha iyo maareeyaha guud",
    "about.leadershipDesc": "Khabirka luqadda Ingiriis ee SHEEGOW ACADEMY ka dambeeya.",
    "about.founderBadge": "Aasaasaha & Maareeyaha Guud",
    "about.founderSpecialty": "Khabiir Luqadda Ingiriis · 15+ sano khibrad",
    "about.founderBio": "Ciise wuxuu haystaa digri jaamacad oo Ingiriis ah iyo shahaadooyin luqad badan. 15 sano oo khibrad barasho, wuxuu maamulaa SHEEGOW ACADEMY hal hadaf: caawinta ardayda meel kasta oo Ingiriiska si kalsooni uga hadlaan fasalo isdhaafsi oo live ah.",
    "about.universityDegree": "Digri jaamacad",
    "about.multipleCertificates": "Shahaadooyin luqad badan",
    "about.teaching15Years": "15 sano oo khibrad barasho",
    "about.teacherEyebrow": "La kulul Macallinkaaga",
    "about.teacherTitle": "Hal khabiir. Cashar kasta live.",
    "about.teacherDesc": "Dhammaan koorsooyinka waxaa bari doona aasaasaha Ciise Mohamed Sheeq (SHEEGOW), khabiir Ingiriis oo 15 sano khibrad — live iyo isdhaafsi, ma rikoor.",
    "about.founderTeacherBadge": "Aasaasaha & Macallin",
    "about.viewCourses": "Eeg Koorsooyinka",
    "about.ctaEyebrow": "Bilow maanta",
    "about.ctaTitle": "Ma diyaar tahay inaad bilowso safarka Ingiriiska?",
    "about.ctaDesc": "Ku biir SHEEGOW ACADEMY maanta oo bilow Ingiriiska ku hadashida macallimiin khibrad leh fasallo live ah.",
    "about.askQuestion": "Waydii su'aal",
