    "about.heroDesc": "نحن موجودون لتقديم تعليم إنجليزي عالي الجودة ومباشر للطلاب في كل مكان. لا فيديوهات مسجلة. لا دراسة ذاتية وحيدة. معلمون حقيقيون، محادثات حقيقية، تقدم حقيقي.",
