    "about.getInTouch": "تواصل معنا",
    "about.missionDesc": "جعل تعليم الإنجليزي عالي الجودة والتفاعلي متاحًا لكل متعلم — من خلال فصول مباشرة يدرّسها معلمون خبراء مهتمون. نحن موجودون لكسر حاجز التعلم المسجل السلبي واستبداله بالمحادثة والممارسة والثقة.",
    "about.visionDesc": "عالم يستطيع فيه كل طالب — من المدرسة الابتدائية إلى المحترف العامل — التحدث بالإنجليزية بثقة. حيث تحل الفصول المباشرة محل الفيديوهات الوحيدة، حيث يعرف المعلمون طلابهم بأسمائهم، وحيث المستقبل الأفضل على بعد فصل مباشر.",
    "about.storyEyebrow": "القصة",
    "about.storyTitle": "مبني للمتعلمين، من قبل المتعلمين",
    "about.storyP1": "بدأت أكاديمية شيغو بإحباط بسيط: الكثير من دورات الإنجليزي كانت مجرد تسجيلات. شاهدت فيديو، أجبت اختبارًا، ونسيت كل شيء. لم يكن هناك تحدث أو ممارسة أو محادثة حقيقية — الأشياء التي تجعل اللغة تثبت.",
    "about.storyP2a": "مؤسسنا والمدير العام،",
    "about.storyP2b": "، قرر إصلاح هذا. خبير لغة إنجليزية حاصل على شهادة جامعية، يحمل شهادات لغوية متعددة ويجلب 15 عامًا من خبرة التدريس. بنينا منصة كل فصل فيها",
    "about.storyP2c": ". حيث ترى معلمك، تسمع زملاءك، ترفع يدك، وتتحدث الإنجليزية بصوت عالٍ من اليوم الأول.",
    "about.storyP3": "اليوم، يتعلم الطلاب معنا — من المبتدئين تمامًا في أول فصل إلى مرشحي IELTS الذين يستعدون للجامعة في الخارج. نتعلم على الهواتف وأجهزة الكمبيوتر. نأتي من دول مختلفة، لكننا نتشارك هدفًا واحدًا: التحدث بالإنجليزية بثقة.",
    "about.storyP4a": "هذا هو فرق شيغو.",
    "about.storyP4b": "فصول مباشرة، لا فيديوهات مسجلة.",
    "about.valuesEyebrow": "قيمنا",
    "about.valuesTitle": "بماذا نؤمن",
    "about.valuesDesc": "ستة مبادئ تشكل كل فصل وكل دورة وكل قرار نتخذه.",
    "about.valueLiveFirstTitle": "التعلم المباشر أولًا",
    "about.valueLiveFirstDesc": "نؤمن أن الإنجليزية مخصصة للتحدث لا للمشاهدة. كل فصل هو جلسة فيديو في الوقت الفعلي مع معلم.",
    "about.valueAccessibleTitle": "متاح للجميع",
    "about.valueAccessibleDesc": "يجب أن يصل تعليم الإنجليزي عالي الجودة لكل متعلم حول العالم يريد تعلم الإنجليزية — بغض النظر عن نقطة البداية.",
    "about.valueQualityTitle": "تدريس عالي الجودة",
    "about.valueQualityDesc": "معلمونا حاصلون على شهادة TESOL ومتخصصون في تدريس الإنجليزية لطلاب من كل خلفية.",
    "about.valueCommunityTitle": "المجتمع",
    "about.valueCommunityDesc": "التعلم اجتماعي. نبني مجموعات صغيرة وداعمة حيث يتدرب الطلاب معًا وينمون معًا.",
    "about.valueRespectTitle": "احترام الثقافات",
    "about.valueRespectDesc": "نحترم كل ثقافة وخلفية. دروسنا تساعدك على فتح أبواب جديدة دون ترك هويتك.",
    "about.valueImprovementTitle": "تحسين مستمر",
    "about.valueImprovementDesc": "نستمع لملاحظات الطلاب كل أسبوع ونحسّن دوراتنا لخدمتك بشكل أفضل.",
    "about.leadershipEyebrow": "القيادة",
    "about.leadershipTitle": "تعرّف على المؤسس والمدير العام",
    "about.leadershipDesc": "خبير اللغة الإنجليزية وراء أكاديمية شيغو.",
    "about.founderBadge": "المؤسس والمدير العام",
    "about.founderSpecialty": "خبير لغة إنجليزية · +15 عامًا من الخبرة",
    "about.founderBio": "سيسي حاصل على شهادة جامعية في الإنجليزية وشهادات لغوية متعددة. بـ15 عامًا من خبرة التدريس، يقود أكاديمية شيغو بهدف واحد: مساعدة المتعلمين في كل مكان على التحدث بالإنجليزية بثقة عبر فصول تفاعلية مباشرة.",
    "about.universityDegree": "شهادة جامعية",
    "about.multipleCertificates": "شهادات لغوية متعددة",
