    "about.teacherTitle": "خبير واحد. كل فصل مباشر.",
    "about.teacherDesc": "جميع الدورات يدرّسها المؤسس سيسي محمد شيخ (شيغو)، خبير لغة إنجليزية بـ15 عامًا من الخبرة — مباشر وتفاعلي، لا مسجل أبدًا.",
    "about.founderTeacherBadge": "المؤسس والمعلم",
